import{_ as a,C as d,o,c as n,E as r,a2 as l}from"./chunks/framework.Cm6XCzck.js";const C=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.6","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.6","outline":"deep"},"headers":[],"relativePath":"zh/publications/implementation-case-i0.6/part-01.md","filePath":"zh/publications/implementation-case-i0.6/part-01.md","lastUpdated":1786085052000}'),s={name:"zh/publications/implementation-case-i0.6/part-01.md"};function i(p,t,c,h,P,g){const e=d("ArticleCover");return o(),n("div",null,[r(e,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"面向 S0.5 Reference Reader、FCoP、CodeFlowMu 与 WP-13 的作者本地工程证据基线。",version:"I0.6",status:"S0.5 工程证据草稿",languageHref:"/en/publications/implementation-case-i0.6",languageLabel:"English"}),t[0]||(t[0]=l(`<h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="s0-5-reference-reader、fcop-v3-2-5、codeflowmu-本地快照与-wp-13" tabindex="-1">S0.5 Reference Reader、FCoP v3.2.5、CodeFlowMu 本地快照与 WP-13 <a class="header-anchor" href="#s0-5-reference-reader、fcop-v3-2-5、codeflowmu-本地快照与-wp-13" aria-label="Permalink to &quot;S0.5 Reference Reader、FCoP v3.2.5、CodeFlowMu 本地快照与 WP-13&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> Draft I0.6<br><strong>状态：</strong> 作者生成的实施与案例报告<br><strong>规范目标：</strong> <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a><br><strong>历史基线：</strong> I0.5 保留 S0.4 语料库与 WP-13 出版包<br><strong>证据采集：</strong> 2026-08-07，Asia/Shanghai<br><strong>证据包：</strong> <code>tmpa-i0.6-local-evidence-20260806-v2</code><br><strong>权威边界：</strong> 本报告仅提供工程证据，不具有规范性；TMPA 要求只由 Core Specification 定义。</p></blockquote><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>I0.6 是首次使用新鲜产品证据对 TMPA Core S0.5 进行评估的 Implementation Case 修订。它严格分开四条轨道：S0.5 Reference Reader、FCoP v3.2.5 协议参考实现、从本地 CodeFlowMu 工作树逐字节隔离的运行快照，以及已经发布的 WP-13 多 Agent 证据门控案例。小典 AI 仍是工程谱系与候选现场案例；本轮没有可锁定的小典 S0.5 包，因此未运行。</p><p>S0.5 Reference Reader 在作者生成的合成 Fixture 上 <strong>14/14 PASS</strong>，但产品证据不继承这些结果。产品矩阵为 <strong>1 PASS、8 PARTIAL、3 NOT RUN、2 FAIL</strong>：C14 PASS；C02、C07 FAIL；C01、C03–C06、C09、C10、C13 PARTIAL；C08、C11、C12 NOT RUN。FCoP 记录 1,222 项通过、3 项失败、2 项跳过；CodeFlowMu 记录 Protocol Fixture 8/8、Runtime 1,420 通过 / 1 失败 / 1 跳过、Shell 770/770，Protocol、Runtime、Shell Typecheck 均通过。</p><p>因此，本报告支持“已实现”和“作者运行并演示”的工程结论，不支持完整 S0.5 一致性、独立验证或独立采用。失败项作为证据保留。WP-13 演示的是对未经验证完成声明的治理遏制，不证明模型已经停止产生幻觉。</p><h1 id="_1-范围与研究问题" tabindex="-1">1. 范围与研究问题 <a class="header-anchor" href="#_1-范围与研究问题" aria-label="Permalink to &quot;1. 范围与研究问题&quot;">​</a></h1><p>本报告回答四个问题：</p><ol><li>已发布的 Reference Reader 能否确定性执行 S0.5 规范解释？</li><li>FCoP 与 CodeFlowMu 当前有哪些 S0.5 产品级证据？</li><li>产品行为在哪些位置仍与 Core 契约不闭合？</li><li>WP-13 对不确定工具结果下的多 Agent 证据门控演示了什么？</li></ol><p>判断单元是“绑定到某项标准的证据声明”，不是对产品的总体声誉判断。四级证据必须分开：</p><table tabindex="0"><thead><tr><th>层级</th><th>I0.6 中的含义</th></tr></thead><tbody><tr><td>Specified</td><td>由 TMPA Core S0.5 定义</td></tr><tr><td>Implemented</td><td>代码或协议工件中存在对应机制</td></tr><tr><td>Demonstrated</td><td>作者运行产生可检查证据</td></tr><tr><td>Independently Adopted</td><td>独立组织采用并验证该机制</td></tr></tbody></table><p>I0.6 没有任何声明达到 Independently Adopted。</p><h1 id="_2-架构与组件边界" tabindex="-1">2. 架构与组件边界 <a class="header-anchor" href="#_2-架构与组件边界" aria-label="Permalink to &quot;2. 架构与组件边界&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture</span></span>
<span class="line"><span>       ↓ 规范契约</span></span>
<span class="line"><span>TMPA Core S0.5</span></span>
<span class="line"><span>       ↓ 可复用协议 Profile</span></span>
<span class="line"><span>FCoP 协议</span></span>
<span class="line"><span>       ↓ 参考实现</span></span>
<span class="line"><span>fcop / fcop-mcp</span></span>
<span class="line"><span>       ↓ 下游采用</span></span>
<span class="line"><span>CodeFlowMu 应用与 WP-13 工作流</span></span></code></pre></div><p>TMPA 是治理架构。FCoP 是可复用协议 Profile，不是应用程序，也不能用“<code>pip install</code> 了一个产品”来定义协议。<code>fcop</code> 与 <code>fcop-mcp</code> Package 是协议参考实现。CodeFlowMu 是下游应用，使用 FCoP 概念和操作实现持久角色、任务、报告、复核、恢复与审计表面。WP-13 是一个有界 CodeFlowMu 现场案例。小典 AI 属于工程谱系，但本轮未作为 S0.5 产品输入执行。</p><p>概念分层与历史谱系必须分开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>概念分层：TMPA → FCoP → CodeFlowMu / 其他应用</span></span>
<span class="line"><span>历史谱系：小典实践 → 早期 TMPA → FCoP 提炼</span></span>
<span class="line"><span>                               → CodeFlowMu → 当前 TMPA 形式化</span></span></code></pre></div><h1 id="_3-证据设计与固定来源" tabindex="-1">3. 证据设计与固定来源 <a class="header-anchor" href="#_3-证据设计与固定来源" aria-label="Permalink to &quot;3. 证据设计与固定来源&quot;">​</a></h1><p>V2 包保留命令、环境、stdout/stderr、结构化摘要、标准矩阵、来源清单、隐私脱敏报告与 SHA-256 Manifest。V2 只修正 V1 的叙述错误，没有重跑测试，也没有改变任何原始产品日志。</p><table tabindex="0"><thead><tr><th>来源</th><th>固定身份</th><th>证据作用</th><th>边界</th></tr></thead><tbody><tr><td>TMPA Publication</td><td>Commit <code>653e7ba0…</code></td><td>S0.5 Schema、Fixture、Reference Reader</td><td>作者实现</td></tr><tr><td>FCoP</td><td>Tag <code>v3.2.5</code>，Commit <code>b3dc2343…</code></td><td>协议与干净 detached 参考实现</td><td>公开固定源码</td></tr><tr><td>CodeFlowMu</td><td>Base <code>c4ebc146…</code>，<code>0.3.0-alpha</code></td><td>隔离产品/测试快照</td><td>脏本地源码：39 Modified、47 Untracked</td></tr><tr><td>WP-13</td><td>Commit <code>609571dd…</code>，V3 ZIP SHA-256 <code>5b5eda30…</code></td><td>多 Agent 事实复核案例</td><td>作者生成、角色分离 QA；非第三方验证</td></tr><tr><td>小典 AI</td><td>无固定 S0.5 包</td><td>谱系与候选案例</td><td>NOT RUN</td></tr></tbody></table><p>CodeFlowMu 运行时使用与工作树逐字节一致的隔离快照，但它不是稳定公开 Release，只能支持作者本地工程证据。</p><h1 id="_4-fcop-与-codeflowmu-工程映射" tabindex="-1">4. FCoP 与 CodeFlowMu 工程映射 <a class="header-anchor" href="#_4-fcop-与-codeflowmu-工程映射" aria-label="Permalink to &quot;4. FCoP 与 CodeFlowMu 工程映射&quot;">​</a></h1><p>FCoP 通过带路由的文本对象、生命周期路径、原子发布、追加式迁移、明确角色、独立 REPORT/REVIEW、ISSUE、ALERT 与 History 提供项目可见协作。它使协调事实在短暂 Agent Session 之外仍可检查和重建。</p><p>CodeFlowMu 在协议之上增加应用运行行为：持久工作身份、PM/DEV/QA/OPS 角色界面、Skill 与工具调用、Workflow 调度、Review Gate、依赖等待、恢复、审批边界及用户界面。这些机制可以实现或演示部分 S0.5，但不能重定义 FCoP 协议或 TMPA Core 标准。</p><p>共同的主要缺口是受维护的产品投影：把原生工件转换成完整 S0.5 Governance Object 与 Reader Result 表面。在该投影完成前，局部门禁可以工作，但规范对象、Issue Code、三值判断与确定性聚合视图仍可能不完整。</p><h1 id="_5-已执行测试基线" tabindex="-1">5. 已执行测试基线 <a class="header-anchor" href="#_5-已执行测试基线" aria-label="Permalink to &quot;5. 已执行测试基线&quot;">​</a></h1><p>所有主运行均由作者执行。Reference Reader PASS 不得复制为 Product PASS。</p><table tabindex="0"><thead><tr><th>轨道</th><th style="text-align:right;">结果</th><th style="text-align:right;">Exit</th><th>解释</th></tr></thead><tbody><tr><td>S0.5 Reference Reader</td><td style="text-align:right;">14 PASS</td><td style="text-align:right;">0</td><td>合成 Fixture 上的可执行规范解释</td></tr><tr><td>FCoP v3.2.5 全量</td><td style="text-align:right;">1,222 PASS、3 FAIL、2 SKIP</td><td style="text-align:right;">1</td><td>保留三项产品断言失败</td></tr><tr><td>FCoP Library CI 子集</td><td style="text-align:right;">907 PASS、1 FAIL</td><td style="text-align:right;">1</td><td><code>parent</code> 持久化/读回缺口</td></tr><tr><td>FCoP MCP CI 子集</td><td style="text-align:right;">78 PASS、2 FAIL</td><td style="text-align:right;">1</td><td>Report Lifecycle 与 Tool Surface Snapshot 缺口</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">8/8</td><td style="text-align:right;">0</td><td>5 个合法与 3 个预期非法 Fixture</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,420 PASS、1 FAIL、1 SKIP</td><td style="text-align:right;">1</td><td>一项人工提示语契约不匹配</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">770/770</td><td style="text-align:right;">0</td><td>完整隔离 Shell Snapshot</td></tr><tr><td>三包 Typecheck</td><td style="text-align:right;">全部通过</td><td style="text-align:right;">0</td><td>仅静态检查</td></tr><tr><td>WP-13 V3 验证</td><td style="text-align:right;">PASS</td><td style="text-align:right;">0</td><td>23/23 内部 Hash 与结构化数据检查</td></tr></tbody></table><p>两份 FCoP stdout 被规范化为可解码 UTF-8，并含 U+FFFD 替换字符。计数、退出码与已识别失败项未受影响，但证据包不声明原始进程输出得到逐字节无损保存。</p>`,30))])}const S=a(s,[["render",i]]);export{C as __pageData,S as default};
